INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 1, 'theory', 'Quiz: the computer and levels of abstraction');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 1, 0, 'What is abstraction in the design of complex systems?', '["A simplified drawing of the system", "Leaving out the details that do not matter for the current task", "Replacing complex parts with cheap ones", "Describing the system in one sentence"]', 1, 'Abstraction lets you work at a suitable level and forget the lower ones: a politician looks at districts, not at every yard.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 1, 1, 'How does architecture differ from microarchitecture?', '["It does not: they are synonyms", "Architecture concerns memory, microarchitecture concerns the processor", "Microarchitecture defines the programming language", "Architecture is what the programmer sees (instructions, registers); microarchitecture is how it is implemented with gates"]', 3, 'The Core i7, 80486, and Athlon share one x86 architecture but have different microarchitectures: their price, speed, and power consumption differ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 1, 2, 'Which principle requires every module to have a clearly defined function and interface?', '["Hierarchy", "Regularity", "Modularity", "Design discipline"]', 2, 'Modularity: a module can be connected to others without side effects, relying only on its interface. Hierarchy divides a system into parts, regularity reuses identical blocks.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 1, 3, 'How much information does a variable carry if it takes one of 8 equally likely states?', '["1 bit", "3 bits", "8 bits", "256 bits"]', 1, 'D = log₂ N: log₂ 8 = 3 bits. A binary variable is 1 bit, and the ten positions of a Babbage gear are about 3.32 bits.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 1, 4, 'Why are modern systems built from digital circuits, even though digital circuits are a special case of analog ones?', '["Digital circuits are the cheapest", "Analog circuits do not exist", "Digital circuits are always faster", "Limiting to two levels is design discipline: it greatly simplifies designing large systems"]', 3, 'Discipline voluntarily narrows the choices, but in return we can build huge systems without thinking about continuous quantities.');
